"""HTML skeleton extraction and heading-based splitting for EPUB chapter detection.

Pure function module — no dependencies on EpubReader, Database, or any other
project module. Works on raw HTML strings.
"""

from __future__ import annotations

import html as html_mod
import re

# ── Noise class patterns ────────────────────────────────────────────────
# These CSS classes are auto-generated by tools like Calibre and carry no
# semantic meaning for heading detection. Filtering them keeps the skeleton
# clean for the LLM.
_NOISE_CLASS_RE = re.compile(
    r"^(?:calibre\d*|sgc-\d+|sgc-toc-\d+|block_\d+|tapuz_.*|"
    r"filepos\d*|fs-\d+|id\d+|index\d+|list\d+|item\d+|"
    r"para\d+|sec\d+|sect\d+|sub\d+|txt\d+)$",
    re.IGNORECASE,
)

# Tag names whose content we care about for structure analysis
_STRUCTURAL_TAGS = frozenset({
    "h1", "h2", "h3", "h4", "h5", "h6",
    "p", "div", "span", "font", "b", "strong", "i", "em",
    "br", "hr", "img",
})

# Tags to skip entirely (their inner content)
_SKIP_TAGS = frozenset({"style", "script", "head", "meta", "link"})


# ── Inline tag cleaning (moved from epub_reader.py) ─────────────────────


def _clean_inline_tags(inner: str) -> str:
    """Clean inline HTML tags from paragraph inner content.

    Extracted from _format_html so both class-based and no-class <p>
    matching can reuse the same cleaning logic.
    """
    text = re.sub(r"<sup[^>]*>.*?</sup>", "", inner, flags=re.DOTALL)
    text = re.sub(r"<a[^>]*>", "", text)
    text = re.sub(r"</a>", "", text)
    text = re.sub(r"<br\s*/?>", "\n", text)
    text = re.sub(r"<[^>]+>", "", text)
    text = html_mod.unescape(text)
    return text.strip()


# ── Skeleton extraction ──────────────────────────────────────────────────


def extract_html_skeleton(html_content: str, max_chars: int = 2000) -> str:
    """Extract structural skeleton from EPUB XHTML for LLM pattern analysis.

    Preserves tag names, CSS classes, font size attributes, and alignment
    hints. Body text is replaced with ``...`` placeholders. The output is
    compact enough (~500 tokens) for a single cheap LLM call.

    Args:
        html_content: Raw XHTML from a spine item.
        max_chars: Hard cap on output length (default 1200 ≈ ~500 tokens).

    Returns:
        A compact HTML skeleton string suitable for heading-pattern identification.
    """
    # Find <body> — if missing, use the full string
    body_match = re.search(r"<body[^>]*>(.*?)</body>", html_content, re.DOTALL | re.IGNORECASE)
    if body_match:
        inner = body_match.group(1)
    else:
        inner = html_content

    # Normalise whitespace
    inner = re.sub(r"[ \t]+", " ", inner)
    inner = re.sub(r"\n{3,}", "\n\n", inner)

    # Tokenise into tag-or-text stream
    tokens = re.split(r"(<[^>]+>)", inner)
    result: list[str] = []
    char_count = 0
    skip_depth = 0

    for token in tokens:
        if char_count >= max_chars:
            result.append("<!-- truncated -->")
            break

        if not token:
            continue

        # Text node
        if not token.startswith("<"):
            stripped = token.strip()
            if stripped:
                result.append("...")
                char_count += 3
            continue

        # Closing tag
        if token.startswith("</"):
            tag_name = token[2:-1].lower().split()[0]
            if skip_depth > 0 and tag_name in _SKIP_TAGS:
                skip_depth -= 1
                continue
            result.append(token)
            char_count += len(token)
            continue

        # Self-closing tag
        if token.endswith("/>") or token.lower().startswith("<br"):
            tag_name = token[1:].lstrip("/").split()[0].lower().rstrip(">").rstrip("/")
            if tag_name in ("br", "hr", "img"):
                result.append(token)
                char_count += len(token)
            continue

        # Opening tag — extract tag name
        inner_tag = token[1:-1].split()[0].lower().rstrip(">")
        tag_name = inner_tag.lstrip("/")

        if tag_name in _SKIP_TAGS:
            skip_depth += 1
            continue

        if tag_name not in _STRUCTURAL_TAGS:
            continue

        # Build simplified tag
        simplified = _simplify_opening_tag(token, tag_name)
        if simplified:
            result.append(simplified)
            char_count += len(simplified)

    return "".join(result)


def _simplify_opening_tag(raw_tag: str, tag_name: str) -> str | None:
    """Extract key attributes from an opening tag, discarding noise."""
    attrs = raw_tag[len(tag_name) + 1:-1].strip()  # content between <tagname and >

    # Extract class
    class_val = ""
    class_m = re.search(r'class\s*=\s*"([^"]*)"', attrs, re.IGNORECASE)
    if class_m:
        classes = class_m.group(1).split()
        meaningful = [c for c in classes if not _NOISE_CLASS_RE.match(c)]
        if meaningful:
            class_val = " ".join(meaningful)

    # Extract font size (from <font size="N">)
    font_size = ""
    font_m = re.search(r'size\s*=\s*["\']?(\d+)', attrs, re.IGNORECASE)
    if font_m:
        font_size = font_m.group(1)

    # Extract align (from <p align="center">)
    align = ""
    align_m = re.search(r'align\s*=\s*["\']?(center|right|left)', attrs, re.IGNORECASE)
    if align_m:
        align = align_m.group(1)

    # Build the simplified tag
    parts = [tag_name]
    if class_val:
        parts.append(f'class="{class_val}"')
    if font_size:
        parts.append(f'size="{font_size}"')
    if align:
        parts.append(f'align="{align}"')

    if len(parts) == 1 and tag_name in ("p", "div", "span", "font", "b", "strong", "i", "em"):
        # Bare structural tag with no distinguishing attributes — skip for compactness
        return None

    return f"<{' '.join(parts)}>"


# ── Heading-based HTML splitting ─────────────────────────────────────────


def split_html_by_heading(
    html_content: str,
    method: str,
    selector: str = "",
) -> list[tuple[str, str, str]]:
    """Split raw HTML at heading boundaries.

    Locates chapter/section headings using one of three detection methods,
    then splits the HTML into (heading_text, body_html, matched_tag) tuples.

    Args:
        html_content: Raw XHTML from a spine item.
        method: One of ``"h_tags"``, ``"font_size"``, ``"css_class"``.
        selector: Method-specific value —
            *h_tags*: unused (matches all <h1>-<h6>)
            *font_size*: font size number as string, e.g. ``"5"``
            *css_class*: CSS class name, e.g. ``"chaptertitle-c"``

    Returns:
        List of ``(heading_text, body_html_snippet, matched_tag)``.
        When no headings are found, returns ``[("", html_content, "")]``.
    """
    if method == "h_tags":
        return _split_by_h_tags(html_content)
    elif method == "font_size":
        return _split_by_font_size(html_content, selector)
    elif method == "css_class":
        return _split_by_css_class(html_content, selector)
    else:
        return [("", html_content, "")]


def _split_by_h_tags(html: str) -> list[tuple[str, str, str]]:
    """Split HTML at <h1>-<h6> boundaries."""
    pattern = re.compile(
        r'<(h[1-6])\b([^>]*)>(.*?)</\1>',
        re.DOTALL | re.IGNORECASE,
    )
    matches = list(pattern.finditer(html))
    if not matches:
        return [("", html, "")]

    result: list[tuple[str, str, str]] = []
    i = 0
    while i < len(matches):
        m = matches[i]
        heading_html = m.group(3)  # inner content
        heading_text = _clean_inline_tags(heading_html)
        if not heading_text:
            i += 1
            continue

        nxt: re.Match | None = matches[i + 1] if i + 1 < len(matches) else None
        start = m.end()
        # 默认边界：下一个标题（无论层级）或文件尾
        end = nxt.start() if nxt else len(html)
        body = html[start:end].strip()

        # Filter: skip headings with negligible body (adjacent headings, TOC-only).
        # 层级感知:当前标题后紧跟「更深层级」标题(h2→h3, 章→节)属正常嵌套结构,
        # 不是无正文占位页 —— 灵魂永生等书 h2"第一章"后直接 h3"第511节"。
        # 只有「同级/更浅层级连续无正文」(h2→h2 空白页、目录页)才算占位。
        text_body = re.sub(r"<[^>]+>", "", body).strip()
        is_nested = bool(nxt) and int(m.group(1)[1]) < int(nxt.group(1)[1])
        if len(text_body) < 50 and not is_nested:
            i += 1
            continue

        # 嵌套吸收:当前标题后紧跟更深层级标题、且当前标题本身无正文
        # (h2"第一章"→h3"第511节"), 若第一个子标题确实携带正文, 则把
        # 子标题+其正文并入当前段 —— 让章标题不是 0 字空壳, 而是承载第一节。
        # 后续子标题(第512/513节)仍独立成段。第二章 h2 后有正文(gap>50)
        # 不触发; 附录 h2 后有导语同样不受影响。
        if len(text_body) < 50 and is_nested:
            sub_end = matches[i + 2].start() if i + 2 < len(matches) else len(html)
            absorbed = html[start:sub_end].strip()
            sub_text = re.sub(r"<[^>]+>", "", absorbed).strip()
            if len(sub_text) >= 50:
                body = absorbed
                i += 2  # 消费掉子标题, 下一次从第三标题继续
                result.append((heading_text, body, m.group(0)))
                continue

        result.append((heading_text, body, m.group(0)))
        i += 1

    if not result:
        return [("", html, "")]
    return result


def _split_by_font_size(html: str, selector: str) -> list[tuple[str, str, str]]:
    """Split HTML at ``<font size='N'><b>heading</b></font>`` boundaries.

    The *selector* is the minimum font size number (e.g. ``"4"`` matches
    size 4, 5, 6, 7).  Matches headings wrapped in <p> or standalone
    <font><b> patterns.
    """
    try:
        min_size = int(selector)
    except (ValueError, TypeError):
        return [("", html, "")]

    # Build size alternation: 4|5|6|7 for min_size=4
    sizes = "|".join(str(s) for s in range(min_size, 8))

    # Match: <p ...> <font size="N"><b>heading</b></font> </p>
    pattern = re.compile(
        r'<p\b[^>]*>\s*'
        r'<font\b[^>]*size\s*=\s*["\']?(' + sizes + r')[^>]*>\s*'
        r'<b\b[^>]*>(.*?)</b>\s*'
        r'</font>\s*'
        r'</p>',
        re.DOTALL | re.IGNORECASE,
    )
    matches = list(pattern.finditer(html))
    if not matches:
        # Also try: <font size="N"><b>...</b></font> not wrapped in <p>
        pattern2 = re.compile(
            r'<font\b[^>]*size\s*=\s*["\']?(' + sizes + r')[^>]*>\s*'
            r'<b\b[^>]*>(.*?)</b>\s*'
            r'</font>',
            re.DOTALL | re.IGNORECASE,
        )
        matches = list(pattern2.finditer(html))

    if not matches:
        return [("", html, "")]

    result: list[tuple[str, str, str]] = []
    for i, m in enumerate(matches):
        heading_text = _clean_inline_tags(m.group(2))
        if not heading_text:
            continue

        start = m.end()
        end = matches[i + 1].start() if i + 1 < len(matches) else len(html)
        body = html[start:end].strip()

        text_body = re.sub(r"<[^>]+>", "", body).strip()
        if len(text_body) < 50:
            continue

        result.append((heading_text, body, m.group(0)))

    if not result:
        return [("", html, "")]
    return result


def _split_by_css_class(html: str, selector: str) -> list[tuple[str, str, str]]:
    """Split HTML at elements carrying a specific CSS class.

    The *selector* is the class name (e.g. ``"chaptertitle-c"``).
    Matches any HTML tag with that class in its class attribute.
    """
    if not selector:
        return [("", html, "")]

    escaped = re.escape(selector)
    # Match: <tag class="...selector..." ...> ... </tag>
    pattern = re.compile(
        r'<(\w+)\b[^>]*class\s*=\s*"[^"]*\b' + escaped + r'\b[^"]*"[^>]*>(.*?)</\1>',
        re.DOTALL | re.IGNORECASE,
    )
    matches = list(pattern.finditer(html))
    if not matches:
        return [("", html, "")]

    result: list[tuple[str, str, str]] = []
    for i, m in enumerate(matches):
        heading_html = m.group(2)
        heading_text = _clean_inline_tags(heading_html)
        if not heading_text:
            continue

        start = m.end()
        end = matches[i + 1].start() if i + 1 < len(matches) else len(html)
        body = html[start:end].strip()

        text_body = re.sub(r"<[^>]+>", "", body).strip()
        if len(text_body) < 50:
            continue

        result.append((heading_text, body, m.group(0)))

    if not result:
        return [("", html, "")]
    return result
